<script lang="ts">
import {onMount} from 'svelte';import type {BreadcrumbContract} from '@unofficial-krds/contracts';import {owned} from './catalog-state.svelte.js';
let p:BreadcrumbContract=$props();let narrow=$state(false);
onMount(()=>{const media=matchMedia('(max-width:767px)');const update=()=>narrow=media.matches;update();media.addEventListener('change',update);return()=>media.removeEventListener('change',update);});
const max=$derived(narrow?2:p.maxVisible??4);const count=$derived(Math.max(1,max-1));const collapsed=$derived(p.items.length>count);const hiddenCount=$derived(collapsed?p.items.length-count:0);const omitted=$derived(p.items.slice(0,hiddenCount));const visible=$derived(p.items.slice(hiddenCount));
$effect(()=>{if(p.omitCurrent===false&&!p.currentItem)throw new TypeError('Breadcrumb currentItem is required when omitCurrent is false');});
</script>
<nav {...owned('breadcrumb','root')} aria-label="브레드크럼"><ol {...owned('breadcrumb','list')}><li {...owned('breadcrumb','item')}><a {...owned('breadcrumb','home')} href={p.home.href}>{p.home.label}</a></li>{#if omitted.length}<li {...owned('breadcrumb','item')}><span {...owned('breadcrumb','separator')} aria-hidden="true"> / </span><span {...owned('breadcrumb','ellipsis')} role="img" aria-label={`생략된 경로: ${omitted.map(item=>item.label).join(', ')}`}>…</span></li>{/if}{#each visible as item(item.id)}<li {...owned('breadcrumb','item')}><span aria-hidden="true" {...owned('breadcrumb','separator')}> / </span>{#if item.href}<a {...owned('breadcrumb','link')} href={item.href}>{item.label}</a>{:else}<span {...owned('breadcrumb','link')}>{item.label}</span>{/if}</li>{/each}{#if p.currentItem&&p.omitCurrent===false}<li {...owned('breadcrumb','item')}><span aria-hidden="true" {...owned('breadcrumb','separator')}> / </span><span {...owned('breadcrumb','link')} aria-current="page">{p.currentItem.label}</span></li>{/if}</ol></nav>
